def refs():
    return [{**s, "subject": "science", "locator": "溫室效應、全球暖化、減緩與調適、海平面、極端天氣、氣候風險與臺灣環境影響", "observedPattern": "公立學校公開自然科試題常以溫室氣體、巴黎協定、海平面與生活防災情境，要求區分成因、影響、減緩和調適；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-cross-global-climate-adaptation-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": "A", "explanation": explanation + "選 A。"}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開自然科資料僅供溫室效應、氣候變遷成因與影響、減緩／調適及防災題型的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公立學校公開自然科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "下列哪一項最能區分天氣與氣候？", {"A": "天氣描述短期大氣狀況；氣候需用較長時間的統計資料描述趨勢與變異", "B": "只要今天很熱，就能證明全球氣候正在變暖", "C": "氣候只指某一天的降雨量", "D": "天氣與氣候完全是同一概念"}, "單次高溫是天氣觀察，氣候判斷需依長期、穩定且有基準的資料，不能用一日事件代替趨勢。", "先確認資料的時間尺度，再判斷它能支撐短期描述或長期趨勢。", ["找出題目資料涵蓋的時間長度。", "判斷單日現象屬於天氣尺度。", "確認氣候需要長期統計與基準比較。", "避免把單次事件直接外推到全球趨勢。", "所以選 A。"], "easy"),
    make(2, "人為排放二氧化碳增加，直接加強全球暖化的主要機制是？", {"A": "增加大氣對地表紅外線能量的吸收與再放射，使能量收支改變", "B": "讓太陽突然產生更多可見光", "C": "使地球完全停止向外放出任何能量", "D": "只改變臭氧層，與地表能量無關"}, "溫室氣體會吸收並再放射地表放出的紅外線；人為增加會改變大氣—地表能量收支，不代表能量完全不離開地球。", "沿著排放—輻射—能量收支鏈逐段檢查，避免用口號代替機制。", ["辨認二氧化碳是溫室氣體。", "確認地表受熱後會放出紅外線。", "說明溫室氣體會吸收並再放射部分紅外線。", "將結果連到平衡溫度與暖化風險變化。", "所以選 A。"], "medium"),
    make(3, "下列哪一項屬於『減緩』氣候變遷，而非主要的『調適』？", {"A": "以再生能源與節能降低電力系統的溫室氣體排放", "B": "把校舍地面墊高以降低淹水損失", "C": "為高溫日增設遮蔭與飲水站", "D": "調整農作期以避開未來較常見的乾旱"}, "減緩針對成因，重點是減少排放或增加碳匯；墊高、遮蔭與調整農作期主要是在降低已預期衝擊的損失。", "先問措施是在減少溫室氣體來源，還是在降低暴露與脆弱度。", ["找出每個措施直接作用的對象。", "辨認再生能源與節能是否降低排放。", "把防洪、遮蔭和農作調整歸入風險回應。", "用成因／衝擊兩分法檢查分類。", "所以選 A。"], "easy"),
    make(4, "校園安裝遮陽棚後，學生在熱浪日較不易中暑。這項措施最合理的分類和限制是？", {"A": "屬於調適，可降低校園暴露與健康風險，但不能單獨減少全球溫室氣體", "B": "屬於減緩，能直接降低全球二氧化碳濃度", "C": "它能消除所有熱浪，不需要氣候資料", "D": "只要有遮陽棚，就不必改善通風或提供飲水"}, "遮陽棚改變人暴露在高溫與輻射下的條件，是調適；它不直接減少排放，且仍需搭配通風、飲水與預警。", "判斷措施作用在排放成因或人與危害的接觸程度。", ["辨認遮陽棚改變的是校園微環境。", "把學生暴露與健康風險列為衝擊端。", "確認它沒有直接減少溫室氣體排放。", "補上遮蔭措施仍有範圍與配套限制。", "所以選 A。"], "medium"),
    make(5, "一個地區連續 30 年的平均夏季溫度上升，但每年仍有幾天特別涼。最適合的解釋是？", {"A": "長期平均趨勢與短期天氣波動可以同時存在，涼日不會自動否定氣候趨勢", "B": "只要有涼日，長期暖化趨勢必然是錯的", "C": "平均溫度上升只代表測量儀器壞掉", "D": "氣候變遷會讓每天的溫度完全相同"}, "氣候是長期統計分布，天氣仍會上下波動；短期冷事件與長期平均上升並不互相排斥。", "把資料分成趨勢、變異與極端事件三層閱讀。", ["確認 30 年資料屬長期氣候尺度。", "辨認幾天涼爽是短期變異。", "比較平均值的趨勢而非單日最大最小值。", "說明兩種時間尺度可同時存在。", "所以選 A。"], "medium"),
    make(6, "若海平面上升使沿海校園淹水風險增加，哪一項最直接降低『暴露』？", {"A": "把重要設備移到較高樓層並設置可關閉的防水閘門", "B": "宣稱海平面資料一定不會改變", "C": "增加校園用電以抵銷海水", "D": "只張貼全球暖化標語而不改變場地"}, "移高設備和防水閘門直接減少設備與進水的接觸，是降低暴露或脆弱度的調適措施；不能消除海平面上升成因。", "先定位風險鏈中的危害、暴露、脆弱度，再選對應的措施。", ["列出海平面上升這個危害。", "找出校園設備與低窪空間的暴露。", "選擇能減少接觸或損害的設計。", "確認它屬於調適而非排放減量。", "所以選 A。"], "medium"),
    make(7, "比較兩個氣候方案時，哪項資料最能避免把單一地點的結果誤推到全球？", {"A": "不同地點、不同時間尺度與共同基準的長期資料，並註明測量不確定性", "B": "只選一個最熱城市的一天資料", "C": "只使用支持方案的年份，刪除其他資料", "D": "把模擬圖的顏色深淺當成實際溫度"}, "全球或區域判斷需跨地點、長期和共同基準的資料，還要交代不確定性；單一地點或圖色不足以支撐外推。", "檢查空間尺度、時間尺度、基準與資料品質四個面向。", ["確認研究要回答的是哪個空間尺度。", "收集多地點的長期可比資料。", "統一基準並記錄測量誤差與缺測。", "再判斷結果能否外推到更大尺度。", "所以選 A。"], "hard"),
    make(8, "某方案能降低都市熱島，卻需要大量用水灌溉。下列評估最完整的是？", {"A": "同時比較降溫效果、用水量、維護成本、受益對象與乾旱時的替代方案", "B": "只要能降溫，就可稱為沒有副作用的最佳方案", "C": "用水增加一定代表全球排放下降", "D": "只看建置當天的溫度，不需長期資料"}, "氣候措施可能有共同效益與取捨；需把效果、資源需求、尺度、成本與極端情境一起評估。", "建立效益—代價—條件矩陣，不讓單一指標取代整體判斷。", ["列出方案直接改善的熱風險。", "補上用水、維護與乾旱時的脆弱點。", "辨認受益者與可能承擔成本的群體。", "比較替代方案並寫出適用條件。", "所以選 A。"], "hard"),
    make(9, "『每年颱風過後都淹水，所以全球暖化一定是唯一原因』這句話問題在哪裡？", {"A": "它把局部事件直接歸因於單一全球因素，未檢查降雨、潮位、地形、排水與土地利用等共同因素", "B": "全球暖化不可能影響任何極端事件", "C": "只要事件重複就不需要其他證據", "D": "淹水只由氣溫決定，與降雨無關"}, "氣候變遷可能改變風險，但個別淹水還受到降雨強度、潮位、地形、排水與土地利用等因素影響，需要資料拆解因果。", "把關聯改寫成可檢驗的多因素風險模型。", ["列出觀察到的淹水事件與時間。", "辨認可能共同造成淹水的自然與人為因素。", "提出需要比較的降雨、潮位、排水與地形資料。", "只在證據足夠時說明氣候因素的貢獻範圍。", "所以選 A。"], "hard"),
    make(10, "氣候變遷報告的結論哪一項最嚴謹？", {"A": "在目前資料與模型假設下，某措施可降低特定地點的熱或洪水風險，但仍需長期監測並檢查成本與公平性", "B": "只要措施有效一次，就能保證所有地區都有效", "C": "減緩和調適可以互相替代，不必說明作用對象", "D": "只要結論支持政策，就不必呈現不確定性"}, "合格結論要標示證據、尺度、假設、限制和可能受益／受影響者，不能把單點結果宣稱為普遍保證。", "使用證據—尺度—策略類型—限制—公平性五欄回查。", ["列出測量或模型真正提供的證據。", "標示結論適用的地點與時間尺度。", "判斷措施是減緩、調適或兼具兩者。", "寫出不確定性、成本與不同群體的影響。", "所以選 A。"], "medium"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
